    account_edge = account_id if str(account_id).startswith("act_") else f"act_{account_id}"

    def meta_get(path, params, timeout=30):
        return requests.post(url, headers=headers, json={
            "client_id": client_id,
            "account_id": account_id,
            "path": path,
